<?php namespace Baruck;
require_once __DIR__ . '/image-fields.php';
$catalog = array_column(mediaCatalog(), null, 'path');
?>
<noscript><p class="rounded-lg bg-paper-deep p-4 text-body">Activez JavaScript pour choisir ou importer les images. Les images déjà enregistrées sont conservées.</p></noscript>
<section data-cover class="rounded-xl border border-line bg-ivory p-6"><h2 class="mb-5 font-display text-title">Image de couverture</h2><?php imageFields('cover', ['src' => $article['cover'] ?? '', 'alt' => $article['cover_alt'] ?? ''], $catalog, true, 'gallery', true, ['alt'=>$english['coverAlt'] ?? '']); ?></section>
<section class="rounded-xl border border-line bg-ivory p-6"><h2 class="font-display text-title">Galerie</h2><p class="mt-2 text-caption text-ink/60">Ajoutez jusqu’à 30 images. Les boutons Monter et Descendre définissent leur ordre.</p><div data-gallery data-field="gallery" data-max="30" class="mt-5 space-y-5"><?php foreach ($gallery as $index => $item): if (!is_array($item) || empty($item['src'])) continue; ?><fieldset data-gallery-item class="rounded-lg border border-line p-4"><legend class="px-2 text-caption font-semibold">Image <?= (int) $index + 1 ?></legend><?php imageFields((string) $index, $item, $catalog, false, 'gallery',true,$english['gallery'][$index] ?? []); ?></fieldset><?php endforeach; ?></div><button type="button" data-gallery-add class="<?= $secondaryClass ?> mt-5">Ajouter une image à la galerie</button><p data-gallery-status role="status" class="mt-3 text-caption text-ink/60"></p></section>
<template id="gallery-item-template"><fieldset data-gallery-item class="rounded-lg border border-line p-4"><legend class="px-2 text-caption font-semibold">Image</legend><?php imageFields('new', [], []); ?></fieldset></template>

<?php if (!empty($article['groups'])): ?>
<section class="space-y-5 rounded-xl border border-line bg-ivory p-6"><h2 class="font-display text-title">Groupes de photos et vidéos conservés</h2><p class="text-caption text-ink/60">Les médias restent ceux de l’article. Complétez leurs textes anglais ; ils sont aussi visibles dans l’aperçu.</p>
<?php foreach (['groupsTitle'=>'Titre des groupes','groupsIntro'=>'Présentation des groupes'] as $key=>$label): ?><p class="break-words text-small"><?= e($article[$key] ?? '') ?></p><?php translationField($label,'english[' . $key . ']',$english[$key] ?? '',$key==='groupsIntro'?2000:240,$key==='groupsIntro'); endforeach; ?>
<?php foreach ($article['groups'] as $index=>$group): $en=$english['groups'][$index] ?? []; ?><fieldset class="min-w-0 space-y-4 rounded-lg border border-line p-4"><legend class="px-2 text-small font-bold"><?= e($group['label']) ?></legend><p class="text-caption"><?= e($group['note'] ?? '') ?></p><?php translationField('Intitulé','english[groups][' . $index . '][label]',$en['label'] ?? '',500); translationField('Précision','english[groups][' . $index . '][note]',$en['note'] ?? '',500); ?>
<?php foreach ($group['photos'] as $photoIndex=>$photo): ?><div class="min-w-0 space-y-2 border-t border-line pt-4"><p class="break-words text-caption"><?= e($photo['alt']) ?><?php if (!empty($photo['caption'])): ?> · <?= e($photo['caption']) ?><?php endif; ?></p><?php translationField('Description de la photo','english[groups][' . $index . '][photos][' . $photoIndex . '][alt]',$en['photos'][$photoIndex]['alt'] ?? '',500); translationField('Légende','english[groups][' . $index . '][photos][' . $photoIndex . '][caption]',$en['photos'][$photoIndex]['caption'] ?? '',500); ?></div><?php endforeach; ?></fieldset><?php endforeach; ?></section>
<?php else: ?><input type="hidden" name="english[groupsTitle]" value=""><input type="hidden" name="english[groupsIntro]" value=""><?php endif; ?>
